pe":"string","description":"Controls live crawling behavior. Available values depend on the active visibility labels.","properties":{},"default":"none","required":[]},"includeWebLinks":{"type":"boolean","description":"Include outbound hyperlinks from the page. Default is false.","properties":{},"required":[]},"renderDynamicPages":{"type":"boolean","description":"Enable JavaScript rendering for dynamic content screenshot. Only works when liveCrawl is set to 'fallback' or 'force'. Default is false.","properties":{},"required":[]},"includeImageLinks":{"type":"boolean","description":"Include image URLs from the page. Default is false.","properties":{},"required":[]},"language":{"type":"string","description":"The language code (2-letter ISO 639-1). Default is 'en'.","properties":{},"default":"en","required":[]},"region":{"type":"string","description":"The region code (2-letter country/region code). Default is 'US'.","properties":{},"default":"US","required":[]},"contentFormat":{"type":"string","description":"The format of the document to return. Can be 'text', 'html', or 'markdown'. Default is 'html'.","properties":{},"default":"html","required":[]}},"required":["url"]},"annotations":{}},{"name":"finance","description":"Get price and volume data for financial instruments including stocks, indices, ETFs, mutual funds, cryptocurrencies, and currency exchange rates.","input_schema":{"type":"object","properties":{"query":{"type":"string","description":"A finance related query, like query for stock price or ETF price.","properties":{},"required":[]},"language":{"type":"string","description":"A 2-letter ISO 639-1 language code for interface language in the search results. Default: 'en'.","properties":{},"default":"en","required":[]},"region":{"type":"string","description":"A 2-letter country/region code for where the results should come from (e.g. 'US', 'JP', 'CN'). Default is 'US'.","properties":{},"default":"US","required":[]}},"required":["query"]},"annotations":{}},{"name"