ties":{},"required":[]},"maxHeight":{"type":"integer","description":"Maximum image height in pixels. Used with imageSize for custom bounds.","properties":{},"required":[]},"minHeight":{"type":"integer","description":"Minimum image height in pixels.","properties":{},"required":[]},"maxWidth":{"type":"integer","description":"Maximum image width in pixels.","properties":{},"required":[]},"minWidth":{"type":"integer","description":"Minimum image width in pixels.","properties":{},"required":[]}},"required":["query"]},"annotations":{}},{"name":"news","description":"Give a query, this tool will return related news articles. e.g. 'Latest technology news'","input_schema":{"type":"object","properties":{"query":{"type":"string","description":"A search query for the news.","properties":{},"required":[]},"maxResults":{"type":"integer","description":"Max number of results to return. Default is 10 and maximum value is 20.","properties":{},"default":10,"required":[]},"language":{"type":"string","description":"A 2-letter ISO 639-1 language code for interface language in the search results. Default: 'en'.","properties":{},"default":"en","required":[]},"region":{"type":"string","description":"A 2-letter country/region code for where the results should come from (e.g. 'US', 'JP', 'CN'). Default is 'US'.","properties":{},"default":"US","required":[]},"location":{"type":"string","description":"Location information in format 'lat:<float>;long:<float>', e.g. 'lat:40.753250;long:-74.003807'. If not specified, could infer location in query.","properties":{},"required":[]},"contentFormat":{"type":"string","description":"The response content format. Values can be 'passage' (a query-dependent snippet from the full document), 'text', 'html', or 'markdown', default is 'text'.","properties":{},"default":"text","required":[]},"maxLength":{"type":"integer","description":"The maximum number of characters in the content field in response. Default value is 10000 characters, and maximum value is 500000 characters.","properties":{},"default":10000,"required":[]}},"required":["query"]},"annotations":{}},{"name":"places","description":"Given a query related with places, this tool will return places information","input_schema":{"type":"object","properties":{"query":{"type":"string","description":"A search query for places, e.g., 'popular restaurants in Seattle, WA'.","properties":{},"required":[]},"language":{"type":"string","description":"A 2-letter ISO 639-1 language code for interface language in the search results. Default: 'en'.","properties":{},"default":"en","required":[]},"region":{"type":"string","description":"A 2-letter country/region code for where the results should come from (e.g. 'US', 'JP', 'CN'). Default is 'US'.","properties":{},"default":"US","required":[]},"location":{"type":"string","description":"Location information in format 'lat:<float>;long:<float>'. If not specified, will use the location information given in query.","properties":{},"required":[]}},"required":["query"]},"annotations":{}},{"name":"sonic","description":"Performs blended multi-vertical search with Sonic ranking. Supports fast and advanced modes.","input_schema":{"type":"object","properties":{"query":{"type":"string","description":"Search query, maximum length: 1000 characters.","properties":{},"required":[]},"region":{"type":"string","description":"A 2-letter country/region code for where the results should come from (e.g. 'US', 'JP', 'CN'). Default is 'US'.","properties":{},"default":"US","required":[]},"language":{"type":"string","description":"Language code for the interface language in the search results. Supports ISO 639-1 (2-letter), ISO 639-2 (3-letter), and BCP 47 language tags. Default: 'en'.","properties":{},"default":"en","required":[]},"location":{"type":"string","description":"Location information in format 'lat:<float>;long:<float>'. If not specified, will use the location information given in query.","properties":{},"required":[]},"contentFormat":{"type":"string","description":"The response content format for Description. Values can be 'text', 'html', 'markdown' or 'passage'. Default is 'html'.","properties":{},"default":"html","required":[]},"mode":{"type":"string","description":"The search mode. 'fast' prioritizes speed, 'advanced' prioritizes comprehensiveness. Default is 'fast'.","properties":{},"default":"fast","required":[]},"responseFilter":{"type":"array","description":"List of answer types to include in the response. Supported values: webResults, newsResults, financeResults.","properties":{},"required":[],"items":{"type":"string","properties":{},"required":[]}},"maxResultsWeb":{"type":"integer","description":"Maximum number of web results to return.","properties":{},"default":10,"required":[]},"maxLength":{"type":"integer","description":"Maximum character length for content in the response.","properties":{},"default":10000,"required":[]}},"required":["query"]},"annotations":{}},{"name":"sports","description":"Retrieves game schedules for specified sports events or tournaments (e.g., 'World Cup', 'NBA', 'PGA Tour', 'French Open').","input_schema":{"type":"object","properties":{"query":{"type":"string","description":"A sports-related query.","properties":{},"required":[]},"freshness":{"type":"string","description":"The time range to filter results based on discovery date. Supports 'day', 'week', 'month', 'year' for relative time, or ISO 8601 date interval format: 'YYYY-MM-DD/YYYY-MM-DD' or 'YYYY-MM-DDTHH:mm:ssZ/YYYY-MM-DDTHH:mm:ssZ' for a date/datetime range, use .. to omit start or end date.","properties":{},"required":[]},"language":{"type":"string","description":"A 2-letter ISO 639-1 language code for interface language in the search results. Default: 'en'.","properties":{},"default":"en","required":[]},"region":{"type":"string","description":"A 2-letter country/region code for where the results should come from. Default is 'US'.","properties":{},"default":"US","required":[]}},"required":["query"]},"annotations":{