n":"Filter videos by duration range. Values: 'short' (<5 min), 'medium' (5-20 min), 'long' (>20 min). When not set, no filtering is applied.","properties":{},"required":[]}},"required":["query"]},"annotations":{}},{"name":"web","description":"Give a query, this tool will return related contents from web pages. e.g. 'Popular cat breeds in America'","input_schema":{"type":"object","properties":{"query":{"type":"string","description":"A search query string. Supports 'site:' and '-site:' operators to include or exclude results from specific sites (e.g. 'query site:example.com'). Use these operators only when necessary, as they inherently reduce result relevance.","properties":{},"required":[]},"maxResults":{"type":"integer","description":"Max number of results to return. Default is 10 and maximum value is 50.","properties":{},"default":10,"required":[]},"language":{"type":"string","description":"A 2-letter ISO 639-1 language code for interface language in the search results. Default: 'en'.","properties":{},"default":"en","required":[]},"region":{"type":"string","description":"A 2-letter country/region code for where the results should come from (e.g. 'US', 'JP', 'CN'). Default is 'US'.","properties":{},"default":"US","required":[]},"location":{"type":"string","description":"Location information in format 'lat:<float>;long:<float>'.","properties":{},"required":[]},"contentFormat":{"type":"string","description":"The response content format. Values can be 'passage' (a query-dependent snippet from the full document), 'text', 'html', or 'markdown', default is 'html'.","properties":{},"default":"html","required":[]},"maxLength":{"type":"integer","description":"The maximum number of characters in the content or passage field in response. Default value is 10000 characters, and maximum value is 500000 characters.","properties":{},"default":10000,"required":[]},"safeSearch":{"type":"string","description":"Level of safe search filtering. Values: 'off', 'strict'. Default is 'strict'.","properties":{},"default":"strict","required":[]}},"required":["query"]},"annotations":{}}]},"output_index":0,"sequence_number":5}

